import json
import itertools

def solve_puzzle():
    # Input variables (puzzle parameters)
    houses = [1, 2]  # House numbers from left to right
    names = ["Eric", "Arnold"]
    foods = ["pizza", "grilled cheese"]

    n = len(houses)

    # Sanity checks
    assert len(names) == n and len(foods) == n, "Each category must have exactly one value per house."

    solutions = []

    # Enumerate all possible assignments (permutations ensure uniqueness across houses)
    for name_perm in itertools.permutations(names, n):
        for food_perm in itertools.permutations(foods, n):
            # Apply clues (constraints)
            # 1. The person who is a pizza lover is in the second house.
            if food_perm[1] != "pizza":
                continue

            # 2. Arnold is not in the first house.
            if name_perm[0] == "Arnold":
                continue

            # If all constraints are satisfied, record the solution
            assignment = []
            for i in range(n):
                assignment.append({
                    "House": str(houses[i]),
                    "Name": name_perm[i],
                    "Food": food_perm[i],
                })
            solutions.append(assignment)

    # Choose the first solution (the puzzle should have a unique solution)
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    solution = solutions[0]

    # Build the required JSON structure
    output = {
        "solution": {
            "header": ["House", "Name", "Food"],
            "rows": [[row["House"], row["Name"], row["Food"]] for row in solution]
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
